def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_last, opp_last = history[-1]
    remaining = 100 - n

    opp_def = sum(1 for a, b in history if b == 'D')
    my_def = sum(1 for a, b in history if a == 'D')

    # Endgame: if opponent has defected, punish until end.
    if remaining <= 15:
        if opp_def > 0:
            return 'D'
        if remaining == 1:
            return 'D'
        return 'C'

    # If opponent defected last round:
    if opp_last == 'D':
        # If opponent has defected a lot, defect.
        if opp_def >= 4 and opp_def * 2 >= n:
            return 'D'
        # If opponent rarely defects, forgive (cooperate).
        if opp_def <= max(1, n // 10):
            return 'C'
        # If we just defected, maybe forgive to break cycle.
        if my_last == 'D' and opp_def <= n // 2:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated.
        # Occasionally probe very cooperative opponents.
        if opp_def == 0 and n >= 10 and n % 10 == 0:
            if rng.random() < 0.2:
                return 'D'
        return 'C'
